use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-grouping-lower-bound");let src=r.join("candidate");let rel="crates/zopro-core/src/msm_affine/grouping.rs";let p=src.join(rel);let s=fs::read_to_string(&p).unwrap();fs::write(r.join("grouping.original.rs"),&s).unwrap();let old="    let reservation = grouping_cost::reserve(scalars.len(), percent)?;";let new=format!("{old}\n    #[cfg(zopro_grouping_lower_bound)]\n    if std::env::var(\"ZOPRO_CPU_GROUPING_LOWER_BOUND\").as_deref()==Ok(\"1\")\n        && lower_bound::declines(scalars,percent) {{ return None; }}");assert_eq!(s.matches(old).count(),1);let after=format!("{}\n#[cfg(zopro_grouping_lower_bound)]\nmod lower_bound;\n",s.replacen(old,&new,1));fs::write(&p,after).unwrap();fs::create_dir_all(src.join("crates/zopro-core/src/msm_affine/grouping")).unwrap();fs::copy(r.join("lower_bound.rs.txt"),src.join("crates/zopro-core/src/msm_affine/grouping/lower_bound.rs")).unwrap();fs::write(r.join("edits.json"),serde_json::to_vec_pretty(&json!({"path":rel,"before_sha256":hash(r.join("grouping.original.rs")),"old":old,"new":new,"appended":"\n#[cfg(zopro_grouping_lower_bound)]\nmod lower_bound;\n"})).unwrap()).unwrap();
 let ex=src.join("crates/zopro-bench/examples");fs::create_dir_all(ex.join("support")).unwrap();for rel in ["cpu-sdk.rs","support/perf.rs"]{fs::copy(Path::new("/home/ubuntu/src/zk-tools/zopro/crates/zopro-bench/examples").join(rel),ex.join(rel)).unwrap();}
 let m:Value=serde_json::from_slice(&fs::read("/tmp/zopro-grouping-module/production-source-manifest.json").unwrap()).unwrap();let mut pins=serde_json::Map::new();for(file,h)in m["source_files_sha256"].as_object().unwrap(){let p=src.join(file);if file==rel{assert_eq!(hash(r.join("grouping.original.rs")),h.as_str().unwrap());}else{assert_eq!(hash(&p),h.as_str().unwrap());}pins.insert(p.display().to_string(),json!(hash(p)));}
 for file in ["crates/zopro-core/src/msm_affine/grouping/lower_bound.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{let p=src.join(file);pins.insert(p.display().to_string(),json!(hash(&p)));}for file in ["prepare-build.rs","lower_bound.rs.txt","design.md"]{let p=r.join(file);pins.insert(p.display().to_string(),json!(hash(&p)));}fs::write(r.join("source-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();
 let old=fs::read_to_string("/tmp/zopro-ready-arithmetic/native-plan.json").unwrap();let mut plan:Value=serde_json::from_str(&old.replace("/tmp/zopro-ready-arithmetic","/tmp/zopro-grouping-lower-bound").replace("zopro_ready_arithmetic","zopro_grouping_lower_bound")).unwrap();plan["environment"]["ZOPRO_CPU_GROUPING_LOWER_BOUND"]=json!("1");plan["steps"][2]["required_tests"]=json!(["msm_affine::grouping::lower_bound::tests::exact_cutoff_and_zero_boundaries","msm_affine::grouping::lower_bound::tests::collisions_only_fall_back","msm_affine::grouping::lower_bound::tests::randomized_words_never_decline_acceptable_cardinality","msm_affine::grouping::lower_bound::tests::bitmap_fits_existing_classes_phase_and_large_paths_skip"]);fs::write(r.join("native-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Candidate changes1original+1newmodule;176pins");}
